(function(){
  const items=[
    {name:'Amla',latin:'Phyllanthus emblica',type:'Fruit',tradition:'Used in classical Ayurvedic preparations and hair rituals.',found:'Amla Fruit Capsules, Brahmi Hair Ritual Oil',note:'Confirm suitability with a qualified professional before ingesting concentrated forms.'},
    {name:'Ashwagandha',latin:'Withania somnifera',type:'Root',tradition:'A root long included in traditional Ayurvedic formulations.',found:'Ashwagandha Root Powder, Warm Sesame Abhyanga Oil',note:'Seek professional advice during pregnancy or when taking medication.'},
    {name:'Bhringraj',latin:'Eclipta prostrata',type:'Leaf',tradition:'Traditionally infused into oils used in scalp and hair rituals.',found:'Neem & Bhringraj Scalp Oil',note:'Topical products should be patch tested.'},
    {name:'Brahmi',latin:'Bacopa monnieri',type:'Leaf',tradition:'A botanical used in traditional oil and powder preparations.',found:'Brahmi Hair Ritual Oil',note:'Botanical identity should be verified on final product documentation.'},
    {name:'Cardamom',latin:'Elettaria cardamomum',type:'Seed',tradition:'An aromatic culinary spice commonly used in chai.',found:'Ginger Cardamom Chai',note:'Contains naturally occurring aromatic compounds.'},
    {name:'Chamomile',latin:'Matricaria chamomilla',type:'Flower',tradition:'A soft floral infusion used in evening tea rituals.',found:'Quiet Evening Blend',note:'Avoid with known sensitivity to daisy-family plants.'},
    {name:'Ginger',latin:'Zingiber officinale',type:'Root',tradition:'A warming culinary root used in tea and food traditions.',found:'Ginger Cardamom Chai',note:'Concentrated forms may not suit everyone.'},
    {name:'Hibiscus',latin:'Hibiscus sabdariffa',type:'Flower',tradition:'A tart, ruby-colored calyx brewed as a caffeine-free infusion.',found:'Rose & Hibiscus Infusion',note:'Check with a professional if you manage blood pressure or take medication.'},
    {name:'Lavender',latin:'Lavandula angustifolia',type:'Flower',tradition:'A fragrant flower used in aromatic home and rest rituals.',found:'Quiet Evening Blend, Lavender Rest Eye Pillow',note:'Discontinue aromatic use if sensitivity occurs.'},
    {name:'Lemongrass',latin:'Cymbopogon citratus',type:'Leaf',tradition:'A citrus-scented grass brewed in botanical infusions.',found:'Tulsi Dawn Tea, Quiet Evening Blend',note:'Use culinary preparations as directed.'},
    {name:'Neem',latin:'Azadirachta indica',type:'Leaf',tradition:'A bitter botanical traditionally used in external cleansing and oil rituals.',found:'Neem Cloud Cleanser, Neem & Bhringraj Scalp Oil',note:'Do not ingest unless under qualified guidance.'},
    {name:'Rose',latin:'Rosa damascena',type:'Flower',tradition:'A fragrant flower used in teas, oils and skincare.',found:'Tulsi Dawn Tea, Rose Botanical Body Oil, Rose & Squalane Face Oil',note:'Fragrant botanicals can irritate sensitive skin; patch test.'},
    {name:'Sandalwood',latin:'Santalum album',type:'Wood',tradition:'Aromatic wood powder used in traditional external paste preparations.',found:'Sandalwood Clay Mask',note:'Source verification is important for protected sandalwood species.'},
    {name:'Sesame',latin:'Sesamum indicum',type:'Seed',tradition:'A stable carrier oil central to many traditional massage preparations.',found:'Warm Sesame Abhyanga Oil, Neem & Bhringraj Scalp Oil',note:'Avoid with sesame allergy.'},
    {name:'Tulsi',latin:'Ocimum tenuiflorum',type:'Leaf',tradition:'An aromatic leaf brewed in household and ceremonial tea traditions.',found:'Tulsi Dawn Tea',note:'Seek guidance for regular concentrated use during pregnancy or alongside medication.'},
    {name:'Turmeric',latin:'Curcuma longa',type:'Rhizome',tradition:'A golden culinary rhizome used across food and traditional preparations.',found:'Turmeric Root Capsules',note:'Professional advice is important with anticoagulants or gallbladder concerns.'}
  ];let active=items[0],query='',type='All';
  const card=item=>`<button class="glossary-card${item.name===active.name?' is-active':''}" data-ingredient="${item.name}" aria-pressed="${item.name===active.name}"><span>${item.type}</span><strong>${item.name}</strong><em>${item.latin}</em></button>`;
  function render(){const grid=document.querySelector('[data-glossary-grid]');if(!grid)return;const rows=items.filter(i=>(type==='All'||i.type===type)&&(`${i.name} ${i.latin} ${i.tradition}`.toLowerCase().includes(query)));grid.innerHTML=rows.length?rows.map(card).join(''):`<div class="empty-state compact"><h3>No ingredient found</h3><p>Try a different spelling or filter.</p></div>`;renderSpotlight();}
  function renderSpotlight(){const el=document.querySelector('[data-ingredient-spotlight]');if(!el)return;el.innerHTML=`<p class="eyebrow">Ingredient spotlight</p><h2>${active.name}</h2><p class="latin">${active.latin}</p><dl><div><dt>Part used</dt><dd>${active.type}</dd></div><div><dt>Tradition</dt><dd>${active.tradition}</dd></div><div><dt>Found in</dt><dd>${active.found}</dd></div></dl><p class="spotlight-note"><strong>Use note:</strong> ${active.note}</p>`;}
  document.addEventListener('DOMContentLoaded',()=>{if(!document.querySelector('[data-glossary-grid]'))return;document.querySelector('[data-glossary-search]')?.addEventListener('input',e=>{query=e.target.value.toLowerCase();render();});document.querySelectorAll('[data-glossary-filter]').forEach(btn=>btn.addEventListener('click',()=>{type=btn.dataset.glossaryFilter;document.querySelectorAll('[data-glossary-filter]').forEach(b=>b.classList.toggle('is-active',b===btn));render();}));document.addEventListener('click',e=>{const btn=e.target.closest('[data-ingredient]');if(btn){active=items.find(i=>i.name===btn.dataset.ingredient)||active;render();document.querySelector('[data-ingredient-spotlight]').scrollIntoView({behavior:'smooth',block:'nearest'});}});render();});
})();
